-- Transactions, savepoints, PRAGMA, ATTACH and the rest.
BEGIN;
BEGIN IMMEDIATE TRANSACTION name;
COMMIT TRANSACTION;
END;
ROLLBACK;
ROLLBACK TRANSACTION TO SAVEPOINT s;
SAVEPOINT s;
RELEASE SAVEPOINT s;
ATTACH DATABASE 'file' AS db KEY 'k';
DETACH db;
PRAGMA sch.page_size;
PRAGMA page_size = 4096;
PRAGMA page_size = -1;
PRAGMA journal_mode(delete);
VACUUM;
VACUUM sch INTO 'file';
ANALYZE sch.t;
REINDEX;
EXPLAIN SELECT 1;
EXPLAIN QUERY PLAN SELECT 1;
